<template>
  <main class="app-shell recruitment-page">
    <section class="top-panel hero-panel"><h1 class="page-title">裁判招募</h1><div class="hero-rule" /></section>
    <div class="tabs" role="tablist" aria-label="招募列表"><button :class="{ active: tab === 'open' }" role="tab" :aria-selected="tab === 'open'" @click="tab = 'open'">可报名 <span v-if="openCount" class="tab-count">{{ openCount }}</span></button><button :class="{ active: tab === 'mine' }" role="tab" :aria-selected="tab === 'mine'" @click="tab = 'mine'">我的申请 <span v-if="mineCount" class="tab-count">{{ mineCount }}</span></button></div>
    <section v-for="item in list" :key="item.id" class="recruit-card">
      <div v-if="tab === 'mine'" class="card-topline"><span></span><span class="status" :class="statusClass(item.myApplicationStatus)">{{ labels[item.myApplicationStatus] || item.myApplicationStatus }}</span></div>
      <h2>{{ item.competitionName }}</h2><div class="meta-grid"><span><i class="meta-icon">◷</i>{{ formatDate(item.competitionDate || item.recruitmentStart) }}</span><span><i class="meta-icon">⌖</i>{{ item.venue || '地点待定' }}</span></div>
      <p v-if="item.description" class="description">{{ item.description }}</p><div v-if="item.requirements" class="requirement"><span>评审要求</span><p>{{ item.requirements }}</p></div>
      <p v-if="tab === 'mine' && item.myReviewRemark" class="review-note">审核意见：{{ item.myReviewRemark }}</p><div v-if="tab === 'mine' && item.myNote" class="submitted-note"><span>我的补充</span>{{ item.myNote }}</div>
      <div class="card-actions"><button v-if="tab === 'open' && !item.myApplicationStatus" class="button primary action-main" @click="openApply(item)">查看详情并报名 <span aria-hidden="true">→</span></button><span v-else-if="tab === 'open'" class="applied-hint">{{ labels[item.myApplicationStatus] || '已提交申请' }}</span><template v-if="tab === 'mine'"><button v-if="canEdit(item)" class="button secondary action-main" @click="openEdit(item)">{{ item.myApplicationStatus === 'REJECTED' ? '修改后重新提交' : '编辑申请' }} <span aria-hidden="true">↗</span></button><button v-if="canWithdraw(item)" class="quiet-danger" @click="withdraw(item)">取消报名</button></template></div>
    </section>
    <div v-if="!list.length" class="empty-state"><span class="empty-icon">✦</span><p>{{ tab === 'mine' ? '还没有提交过申请' : '暂时没有开放中的招募' }}</p></div>
    <div v-if="selected" class="sheet-backdrop" @click.self="closeSheet"><section class="sheet" role="dialog" aria-modal="true" :aria-label="editing ? '编辑申请' : '提交报名'"><button class="sheet-close" type="button" aria-label="关闭" @click="closeSheet">×</button><h2>{{ selected.competitionName }}</h2><p class="sheet-meta">{{ formatDate(selected.competitionDate || selected.recruitmentStart) }} · {{ selected.venue || '地点待定' }}</p><div v-if="selected.requirements" class="sheet-requirement"><span>评审要求</span><p>{{ selected.requirements }}</p></div><label class="confirm-row"><input v-model="confirmed" type="checkbox"><span>我确认可以参加比赛日期</span></label><label class="field">补充说明 <span>选填</span><textarea v-model="note" class="textarea" maxlength="500" placeholder="可填写擅长风格、时间安排等信息" /></label><button class="button primary full submit-button" :disabled="!confirmed || submitting" @click="submitApplication">{{ submitting ? '提交中…' : editing ? '保存并重新提交' : '提交报名' }}</button><button class="sheet-back" type="button" @click="closeSheet">返回列表</button></section></div>
    <JudgeBottomNav :active="'recruitments'" />
  </main>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import JudgeBottomNav from '@/components/JudgeBottomNav.vue'
import { applyRecruitment, fetchMyRecruitmentApplications, fetchRecruitments, updateRecruitmentApplication, withdrawRecruitmentApplication } from '@/api/judge'
const tab = ref('open'), list = ref([]), selected = ref(null), editing = ref(false), confirmed = ref(false), note = ref(''), submitting = ref(false)
const labels = { APPLIED: '待审核', ACCEPTED: '已录用', REJECTED: '需补充', WITHDRAWN: '已撤回' }
const openCount = computed(() => tab.value === 'open' ? list.value.length : 0), mineCount = computed(() => tab.value === 'mine' ? list.value.length : 0)
async function load() { list.value = tab.value === 'open' ? await fetchRecruitments() : await fetchMyRecruitmentApplications() }
function formatDate(value) { if (!value) return '日期待定'; const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value) : new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(d) }
function statusClass(status) { return { APPLIED: 'status-pending', ACCEPTED: 'status-accepted', REJECTED: 'status-rejected', WITHDRAWN: 'status-withdrawn' }[status] || '' }
function canEdit(item) { return ['APPLIED', 'REJECTED'].includes(item.myApplicationStatus) }; function canWithdraw(item) { return ['APPLIED', 'ACCEPTED'].includes(item.myApplicationStatus) }
function openApply(item) { selected.value = item; editing.value = false; confirmed.value = false; note.value = '' }; function openEdit(item) { selected.value = item; editing.value = true; confirmed.value = item.myAvailabilityConfirmed !== false; note.value = item.myNote || '' }; function closeSheet() { selected.value = null; editing.value = false; submitting.value = false }
async function submitApplication() { if (!selected.value || submitting.value) return; submitting.value = true; try { const payload = { availabilityConfirmed: confirmed.value, note: note.value.trim() }; if (editing.value) await updateRecruitmentApplication(selected.value.myApplicationId, payload); else await applyRecruitment(selected.value.id, payload); closeSheet(); await load() } catch (error) { window.alert(error?.response?.data?.message || error?.message || '提交失败，请稍后重试') } finally { submitting.value = false } }
async function withdraw(item) { if (!window.confirm('取消后将退出本场比赛的评审候选，确认取消报名吗？')) return; try { await withdrawRecruitmentApplication(item.myApplicationId); await load() } catch (error) { window.alert(error?.response?.data?.message || error?.message || '操作失败，请稍后重试') } }
onMounted(load); watch(tab, load)
</script>
<style scoped>
.recruitment-page{padding-top:14px}.hero-panel{position:relative;overflow:hidden;padding:19px 18px 17px;background:#17242b}.hero-panel:after{position:absolute;right:-30px;bottom:-58px;width:150px;height:150px;border:1px solid rgba(215,132,52,.35);border-radius:50%;content:''}.hero-mark{margin-bottom:10px;color:#d7873a;font-size:10px;font-weight:800;letter-spacing:1.8px}.hero-rule{width:38px;height:3px;margin-top:15px;background:#d7873a}.tabs{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:4px;border-radius:9px;background:#dde5e1}.tabs button{min-height:42px;border:0;border-radius:6px;color:#52605d;background:transparent;font-size:15px;font-weight:650}.tabs button.active{color:#17242b;background:#fff;box-shadow:0 2px 5px rgba(23,36,43,.09)}.tab-count{display:inline-grid;min-width:18px;min-height:18px;margin-left:3px;place-items:center;border-radius:9px;color:#fff;background:#d17932;font-size:11px}.recruit-card{display:grid;gap:12px;padding:16px 16px 14px;border:1px solid rgba(23,36,43,.1);border-radius:9px;background:#fff;box-shadow:0 8px 20px rgba(23,36,43,.065)}.card-topline,.meta-grid,.card-actions{display:flex;align-items:center;justify-content:space-between;gap:10px}.competition-code{color:#9a5b29;font-size:10px;font-weight:800;letter-spacing:1.5px}.recruit-card h2{margin:0;color:#1c2c35;font-size:19px;line-height:1.3}.meta-grid{justify-content:flex-start;flex-wrap:wrap;color:#667774;font-size:13px}.meta-icon{margin-right:5px;color:#c16d2c;font-style:normal;font-size:15px}.description,.requirement p,.review-note,.submitted-note{margin:0;color:#52605d;font-size:13px;line-height:1.55}.requirement{padding:10px 11px;border-left:3px solid #d7873a;background:#f6f8f5}.requirement span,.submitted-note span,.sheet-requirement span{display:block;margin-bottom:3px;color:#9a5b29;font-size:11px;font-weight:800;letter-spacing:.7px}.status{padding:4px 9px;border:1px solid;border-radius:999px;font-size:12px;font-weight:750}.status-pending{color:#965815;border-color:#f1d3aa;background:#fff8ed}.status-accepted{color:#13704c;border-color:#a8dec7;background:#eefaf4}.status-rejected{color:#a13d2d;border-color:#efc1b7;background:#fff4f1}.status-withdrawn{color:#667085;border-color:#d5dadd;background:#f5f6f6}.submitted-note{padding:8px 10px;border-radius:5px;background:#f7f8f6}.review-note{color:#a13d2d}.card-actions{margin-top:2px}.action-main{min-height:42px;padding:10px 13px;font-size:14px}.action-main span{margin-left:8px;font-size:17px}.applied-hint{color:#667774;font-size:13px}.quiet-danger{border:0;padding:9px 0 9px 10px;color:#a13d2d;background:transparent;font-size:12px;text-decoration:underline;text-underline-offset:3px}.empty-state{padding:56px 0 30px;text-align:center;color:#7a8581}.empty-state p{margin:12px 0;font-size:14px}.empty-icon{color:#d17932;font-size:25px}.sheet-backdrop{position:fixed;inset:0;z-index:30;display:flex;align-items:flex-end;justify-content:center;background:rgba(16,26,30,.38)}.sheet{position:relative;width:min(520px,100%);max-height:90vh;overflow:auto;padding:23px 18px 19px;border-radius:16px 16px 0 0;background:#fff;box-shadow:0 -14px 35px rgba(23,36,43,.2)}.sheet-close{position:absolute;top:12px;right:15px;width:34px;height:34px;border:0;border-radius:50%;color:#52605d;background:#f0f3f1;font-size:24px;line-height:1}.sheet-kicker{margin-bottom:8px;color:#b56b2d;font-size:10px;font-weight:800;letter-spacing:1.5px}.sheet h2{margin:0;color:#1c2c35;font-size:21px}.sheet-meta{margin:7px 0 17px;color:#667774;font-size:13px}.sheet-requirement{margin-bottom:16px;padding:10px 11px;border-radius:5px;background:#f6f8f5}.sheet-requirement p{margin:0;color:#52605d;font-size:13px;line-height:1.5}.confirm-row{display:flex;align-items:center;gap:9px;margin:14px 0 17px;color:#263b42;font-size:14px;font-weight:700}.confirm-row input{width:18px;height:18px;accent-color:#b76325}.field{display:block;color:#263b42;font-size:14px;font-weight:700}.field span{margin-left:5px;color:#89938f;font-size:12px;font-weight:500}.textarea{min-height:100px;margin-top:8px}.submit-button{margin-top:3px}.sheet-back{width:100%;margin-top:9px;border:0;padding:9px;color:#667774;background:transparent;font-size:14px}
</style>
